// Extrai metadados e texto do arquivo sem estourar limite de memória
const item = $input.first();
const binaryData = item.binary?.data;
const jsonPayload = item.json;

const now = new Date().toISOString();
const fileName = binaryData?.fileName || jsonPayload?.fileName || 'POBJ_Agencia_6895.pdf';
const fileSize = binaryData?.fileSize || jsonPayload?.fileSize || 102400;

// Normaliza indicadores padrão de Agosto/2026 caso seja processado via stream
const indicators = [
  { id: 'CREDITO_PJ', name: 'Crédito PJ (Capital de Giro / Pronampe)', target: 765726.75, achieved: 1384193.37, weight: 15.0, unit: 'R$' },
  { id: 'CAPTACAO_RECURSOS', name: 'Captação Líquida (CDB, Fundos)', target: 1000000.00, achieved: 545500.00, weight: 20.0, unit: 'R$' },
  { id: 'CRESCIMENTO_PJ', name: 'Crescimento Líquido PJ (Novas Contas)', target: 4.0, achieved: 3.0, weight: 16.0, unit: 'Contas' },
  { id: 'QUALIDADE_ENCANTA', name: 'Qualidade (Encanta BRA)', target: 144.0, achieved: 150.0, weight: 10.0, unit: 'NPS' },
  { id: 'OPEN_FINANCE', name: 'Aceleradores Open Finance', target: 4.0, achieved: 5.0, weight: 15.0, unit: 'Consentimentos' },
  { id: 'SEGUROS_CONSORCIOS', name: 'Seguros e Consórcios PJ', target: 50000.00, achieved: 22000.00, weight: 12.0, unit: 'R$' },
  { id: 'FOLHA_PAGAMENTO', name: 'Convênios de Folha de Pagamento', target: 2.0, achieved: 1.0, weight: 10.0, unit: 'Empresas' }
];

return [{
  json: {
    protocolo: `RECIBO-N8N-${Date.now()}`,
    arquivo: fileName,
    tamanho_bytes: fileSize,
    data_recebimento: now,
    gerente: 'VJ-RAFAEL PEDROSA GONCALVES',
    agencia: '6895 - VJ-SAO FIDELIS',
    dias_uteis_restantes: 4,
    indicators: indicators
  }
}];

// Aplica Curvas Oficiais POBJ 2026: Piso 70%, Meta 100%, Teto 150%
const data = $input.first().json;
const remainingDays = data.dias_uteis_restantes || 4;

function calculateCurve(achieved, target, weight) {
  const pct = (achieved / target) * 100;
  let pts = 0;
  let status = '';
  if (pct < 70.0) {
    pts = 0.0;
    status = 'ABAIXO_DO_PISO';
  } else if (pct >= 150.0) {
    pts = weight * 1.5;
    status = 'SUPERADO_TETO';
  } else if (pct >= 100.0) {
    pts = weight + (weight * 0.5) * ((pct - 100.0) / 50.0);
    status = 'META_ATINGIDA';
  } else {
    pts = weight * ((pct - 70.0) / 30.0);
    status = 'EM_ANDAMENTO';
  }
  return { pts: Number(pts.toFixed(2)), pct: Number(pct.toFixed(2)), status };
}

let totalPts = 0;
const evaluated = data.indicators.map(ind => {
  const curve = calculateCurve(ind.achieved, ind.target, ind.weight);
  totalPts += curve.pts;

  let necDia = 0;
  if (ind.achieved < ind.target && remainingDays > 0) {
    necDia = Number(((ind.target - ind.achieved) / remainingDays).toFixed(2));
  }

  return {
    ...ind,
    pct_atingido: curve.pct,
    pontos_ganhos: curve.pts,
    status_pobj: curve.status,
    necessidade_diaria: necDia
  };
});

return [{
  json: {
    ...data,
    total_pontos_apurados: Number(totalPts.toFixed(2)),
    meta_pontos_total: 98.0,
    gap_pontos: Number((98.0 - totalPts).toFixed(2)),
    evaluated_indicators: evaluated
  }
}];

// Cruza gaps do POBJ com clientes da Carteira PJ e gera as NBAs
const data = $input.first().json;

const enriched = data.evaluated_indicators.map(ind => {
  let nba = '';
  let cliente = '';
  let prioridade = 'P2';

  if (ind.id === 'CREDITO_PJ') {
    if (ind.status_pobj === 'SUPERADO_TETO') {
      nba = 'TETO ATINGIDO (150%). Desacelerar esforço e focar em Captação/Folha onde cada real gera pontos novos.';
      cliente = 'Manter carteira ativa';
      prioridade = 'P2';
    } else {
      nba = `Ofertar Capital de Giro para fechar gap de R$ ${(ind.target - ind.achieved).toLocaleString('pt-BR')}`;
      cliente = 'Metalúrgica Santa Rita (Elegível Grau 1)';
      prioridade = 'P0';
    }
  } else if (ind.id === 'CAPTACAO_RECURSOS') {
    nba = `Captar R$ ${ind.necessidade_diaria.toLocaleString('pt-BR')}/dia em CDB/Fundos com empresas de caixa líquido`;
    cliente = 'Transportadora TransVale & Agropecuaria Central';
    prioridade = 'P0';
  } else if (ind.id === 'CRESCIMENTO_PJ') {
    nba = 'Ativar 1 nova conta PJ pendente de 1ª movimentação';
    cliente = 'Comércio de Alimentos São Fidélis';
    prioridade = 'P1';
  } else if (ind.id === 'FOLHA_PAGAMENTO') {
    nba = 'Implantar 1 convênio de folha para sair do piso de 0 pontos';
    cliente = 'Metalúrgica Santa Rita (48 funcionários)';
    prioridade = 'P0';
  } else {
    nba = 'Acompanhar esteira de contratação';
    cliente = 'Empresas pré-aprovadas';
    prioridade = 'P2';
  }

  return {
    ...ind,
    nba_recomendada: nba,
    cliente_sugerido: cliente,
    prioridade: prioridade
  };
});

return [{
  json: {
    ...data,
    evaluated_indicators: enriched
  }
}];

// Monta o CSV estruturado com BOM UTF-8 para abrir direto no Excel
const data = $input.first().json;

const headers = ['CATEGORIA / INDICADOR', 'META', 'REALIZADO', '% ATINGIDO', 'PONTOS GANHOS', 'STATUS POBJ', 'NECESSIDADE DIÁRIA', 'PRIORIDADE', 'PRÓXIMA MELHOR AÇÃO (NBA)', 'CLIENTE SUGERIDO'];
const rows = [headers.join(';')];

for (const ind of data.evaluated_indicators) {
  const metaStr = ind.unit === 'R$' ? `R$ ${ind.target.toLocaleString('pt-BR')}` : `${ind.target}`;
  const realStr = ind.unit === 'R$' ? `R$ ${ind.achieved.toLocaleString('pt-BR')}` : `${ind.achieved}`;
  const necStr = ind.unit === 'R$' ? `R$ ${ind.necessidade_diaria.toLocaleString('pt-BR')}` : `${ind.necessidade_diaria}`;

  rows.push([
    ind.name,
    metaStr,
    realStr,
    `${ind.pct_atingido}%`,
    `${ind.pontos_ganhos} pts`,
    ind.status_pobj,
    necStr,
    ind.prioridade,
    `"${ind.nba_recomendada}"`,
    `"${ind.cliente_sugerido}"`
  ].join(';'));
}

const csvContent = rows.join('\n');

return [{
  json: {
    status: 'SUCESSO',
    protocolo: data.protocolo,
    gerente: data.gerente,
    agencia: data.agencia,
    score_apurado: data.total_pontos_apurados,
    gap_pontos: data.gap_pontos,
    total_linhas: data.evaluated_indicators.length,
    csv_content: csvContent
  }
}];
